// RentCollectionsSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/digitenant/reports/rent/collections/list/RentCollectionsSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import RentCollectionsActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const RentCollectionsSchema = {
  entity: 'rental_rent_collections',
  label: 'Rent Collections',
  description: '',
  apiBase: apiRoutes.rentcollections?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: RentCollectionsActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'payments', label: 'Payments', from: 'rent_payments' },
    { key: 'collected', label: 'Rent Collected', from: 'rent_payments.amount', type: 'money' },
    { key: 'avg_payment', label: 'Average Payment', calc: 'collected / payments', type: 'money' },
    { key: 'chg', label: 'Collected vs Previous', calc: 'change(collected)' },
  ],

  remarks: [
    { if: 'payments == 0', tone: 'watch', title: 'No payments', say: 'No rent payments were received in {label}.' },
    { if: 'chg !== null && chg <= -20', tone: 'watch', title: 'Collections dropped', say: '{label}: {collected} collected, down {abs(chg)}% on {prev_label}.' },
    { if: 'true', tone: 'neutral', title: 'Collections', say: '{payments} payments totalling {collected}, averaging {avg_payment}.' },
  ],

  headline: '{label}: {payments} payments, {collected} collected[, {updown} {abs(chg)}% on {prev_label}].',

  // coming periods the report page adds after the history (see forecast.js)
  forecast: [{ key: 'collected', next: 3, method: 'auto', integer: false }, { key: 'payments', next: 3, method: 'auto', integer: true }],
};
